/* SPDX-License-Identifier: GPL-3.0-only
 * Copyright (C) 2026 Leo Kuroshita (@kurogedelic), Hügelton Instruments */
/* FM-1 SPI NOR at runtime: erase / program / read. Used only when
 * FELUCCA_FLASH is 1.
 *
 * Everything that executes while the SFC (XIP) is switched off lives in
 * .ram_text and touches only SFRs, the stack and RAM buffers: no .rodata, no
 * libcalls, no XIP-resident helpers. Call the fl_*_ram() entry points with
 * interrupts disabled. Same sequence as the AC79 SDK flash driver
 * (enter_spi_code, norflash_erase, norflash_wait_ok, exit_spi_code).
 */
#pragma once
#include <stdint.h>
#include "fm1_xip.h"
#include "fm1_capture_gate.h"

#define RAMFN  __attribute__((section(".ram_text"), noinline, used))
#define RAMINL static inline __attribute__((always_inline))

/* XIP (0x02xxxxxx) -> RAM (0x01C0xxxx) is beyond the 23-bit call range:
 * call RAM code through a pointer the compiler cannot fold back. */
static inline void *fl_far(void *p) { void *volatile q = p; return q; }
#define FL_FAR(fn) ((__typeof__(&fn))fl_far((void *)&fn))

#define REG32(a) (*(volatile uint32_t *)(a))
#define SFC_CON         REG32(0x40200u)            /* bit31 busy; [11:8] read mode */
#define SFCENC_CON      (*(volatile uint8_t *)0x40300u)  /* b0 decrypt, b1 plain window */
#define SFCENC_UNENC_H  REG32(0x40308u)            /* WO, XIP (CPU) address */
#define SFCENC_UNENC_L  REG32(0x4030Cu)            /* WO, XIP (CPU) address */
#define SPI0_CON        REG32(0x11C00u)            /* b15 PND, b14 PCLR, b12 DIR=rx */
#define SPI0_BUF        REG32(0x11C08u)
#define IOMAP_CON0      REG32(0x5101Cu)            /* b5: 1 = SFC owns the flash pins */
#define PORTD_OUT       REG32(0x500C0u)            /* PD0 = flash CS# */
#define PORTD_DIR       REG32(0x500C8u)
#define CACHE_CON       REG32(0x1EEE008u)          /* b14 = cache idle */
#define T4_CNT          REG32(0x10804u)            /* TIMER4, 24 MHz free-running */

#define FL_XIP(off)     FM1_XIP(off)              /* fm1_xip.h */
#include "fm1_flash_map.h"                  /* FL_IN, FL_STORE_OK, FL_RANGE_OK, FL_GUARD, FL_JEDEC_OK; per board */

typedef struct { uint32_t sfc_con, spi_con; } fl_saved_t;

RAMINL void fl_csync(void) { __asm__ volatile("csync" ::: "memory"); }
RAMINL void fl_cache_idle(void) { while (!(CACHE_CON & 0x4000u)) ; }
RAMINL void fl_delay(uint32_t n) { volatile uint32_t i = n; while (i--) ; }

RAMINL void fl_cs(int high)
{
    PORTD_DIR &= ~1u;
    if (high) PORTD_OUT |= 1u; else PORTD_OUT &= ~1u;
    fl_delay(10);
}
RAMINL int fl_spi_wait(void)
{
    uint32_t n = 50000000u;
    fl_csync();
    while (!(SPI0_CON & 0x8000u))
        if (--n == 0) break;
    SPI0_CON |= 0x4000u;
    return n ? 0 : -1;
}
RAMINL void fl_tx(uint8_t b)
{
    SPI0_CON |= 8u; SPI0_CON &= ~0x1000u;
    SPI0_BUF = b; fl_spi_wait();
    SPI0_CON &= ~8u;
}
RAMINL uint8_t fl_rx(void)
{
    uint8_t v;
    SPI0_CON |= 8u; SPI0_CON |= 0x1000u;
    SPI0_BUF = 0xFFu; fl_spi_wait();
    v = (uint8_t)SPI0_BUF;
    SPI0_CON &= ~8u;
    return v;
}
RAMINL void fl_addr(uint32_t a) { fl_tx((uint8_t)(a >> 16)); fl_tx((uint8_t)(a >> 8)); fl_tx((uint8_t)a); }
RAMINL uint8_t fl_rdsr(uint8_t cmd) { uint8_t v; fl_cs(0); fl_tx(cmd); v = fl_rx(); fl_cs(1); return v; }
RAMINL void fl_wren(void) { fl_cs(0); fl_tx(0x06); fl_cs(1); }

RAMINL int fl_enter(fl_saved_t *s)
{
    uint32_t mode;
    fl_cache_idle();
    s->sfc_con = SFC_CON;
    s->spi_con = SPI0_CON;
    mode = (s->sfc_con >> 8) & 0xFu;
    if (mode == 6u || mode == 7u)                 /* continuous-read XIP: not handled here */
        return -1;
    fl_csync();
    while ((int32_t)SFC_CON < 0) ;                /* SFC idle */
    SFC_CON = 0;                                  /* XIP OFF from here on */
    IOMAP_CON0 &= ~0x20u;                         /* pins -> SPI0 / GPIO */
    SPI0_CON = 0;
    SPI0_CON = 0x1029u;                           /* SDK default */
    fl_csync();
    return 0;
}
RAMINL void fl_exit(const fl_saved_t *s)
{
    SPI0_CON = s->spi_con;
    IOMAP_CON0 |= 0x20u;
    fl_csync();
    while ((int32_t)SFC_CON < 0) ;
    SFC_CON = s->sfc_con;                         /* XIP back on */
    fl_csync();
}
RAMINL void fl_inval(uint32_t off, uint32_t len)
{
    uint32_t a = FL_XIP(off) & ~31u, e = FL_XIP(off) + len;
    fl_cache_idle();
    for (; a < e; a += 32u) {
        fl_csync();
        __asm__ volatile("flushinv [%0]" :: "r"(a) : "memory");
        fl_csync();
        fl_cache_idle();
    }
}
RAMINL int fl_wait_ready(uint32_t max_us, uint32_t *took_us)
{
    uint32_t t0 = T4_CNT, dt;
    for (;;) {
        dt = (T4_CNT - t0) / 24u;
        if (!(fl_rdsr(0x05) & 1u)) { *took_us = dt; return 0; }
        if (dt > max_us) { *took_us = dt; return -4; }
    }
}

/* ---- entry points: IRQs OFF, args/buffers in RAM ---- */

static RAMFN uint32_t fl_jedec_ram(void)                 /* expect 0x856014 (FL_JEDEC_OK) */
{
    fl_saved_t s; uint32_t id;
    if (fl_enter(&s)) return 0;
    fl_cs(0); fl_tx(0x9F);
    id = (uint32_t)fl_rx() << 16; id |= (uint32_t)fl_rx() << 8; id |= fl_rx();
    fl_cs(1);
    fl_exit(&s);
    return id;
}

static RAMFN int fl_erase4k_ram(uint32_t off, uint32_t *took_us)
{
    fl_saved_t s; int rc;
    if (!FL_GUARD(off, 0x1000u) || (off & 0xFFFu))
        return -1;
    if (fl_enter(&s)) return -2;
    fl_wren();
    if (!(fl_rdsr(0x05) & 2u)) rc = -3;           /* WEL did not set */
    else {
        fl_cs(0); fl_tx(0x20); fl_addr(off); fl_cs(1);
        fl_inval(off, 4096u);
        rc = fl_wait_ready(500000u, took_us);     /* generic NOR max 400 ms */
    }
    fl_exit(&s);
    return rc;
}

static RAMFN int fl_prog_ram(uint32_t off, const uint8_t *src, uint32_t n, uint32_t *took_us)
{
    fl_saved_t s; int rc; uint32_t i;
    if (!FL_GUARD(off, n) ||
        n == 0 || n > 256u || ((off & 0xFFu) + n) > 256u) return -1;    /* one page, no wrap */
    if (fl_enter(&s)) return -2;
    fl_wren();
    if (!(fl_rdsr(0x05) & 2u)) rc = -3;
    else {
        fl_cs(0); fl_tx(0x02); fl_addr(off);
        for (i = 0; i < n; i++) fl_tx(src[i]);
        fl_cs(1);
        fl_inval(off, n);
        rc = fl_wait_ready(10000u, took_us);      /* generic NOR max 3 ms */
    }
    fl_exit(&s);
    return rc;
}

static RAMFN int fl_read_ram(uint32_t off, uint8_t *dst, uint32_t n)   /* 0x0B fast read */
{
    fl_saved_t s; uint32_t i;
    if (fl_enter(&s)) return -2;
    fl_cs(0); fl_tx(0x0B); fl_addr(off); fl_tx(0xFF);
    for (i = 0; i < n; i++) dst[i] = fl_rx();
    fl_cs(1);
    fl_exit(&s);
    return 0;
}

/* ---- XIP side (normal .text) ---- */

/* Once at boot, before any XIP read of the data region: map the data area
 * as an unencrypted XIP window (as the SDK's IOCTL_SET_VM_INFO does). */
static void fl_plain_window_init(void)
{
    SFCENC_CON &= (uint8_t)~2u;
    SFCENC_UNENC_L = FL_XIP(FL_PLAIN_LO);         /* FM-1 0x0208F000 (0x93000); SMK 0x02099000 (0x9D000) */
    SFCENC_UNENC_H = 0x07FFFFFFu;
    SFCENC_CON |= 2u;
    __asm__ volatile("cli" ::: "memory");
    fl_inval(FL_PLAIN_LO, 0x100000u - FL_PLAIN_LO);   /* drop any decrypted lines */
    __asm__ volatile("csync\n\tsti" ::: "memory");
}

static inline uint32_t irq_save(void) { __asm__ volatile("cli" ::: "memory"); return 0; }
static inline void irq_restore(uint32_t f) { (void)f; __asm__ volatile("csync\n\tsti" ::: "memory"); }

/* A Bluetooth controller on core 1 runs from the flash too (fm1_cpu1.h): park core 1 in RAM
 * around each operation that turns the flash off. Without one (or in the loader) these do nothing. */
#ifdef FM1_CPU1_PARK
#define FL_PARK() fm1_cpu1_park()
#define FL_UNPARK() fm1_cpu1_unpark()
#else
#define FL_PARK() 0
#define FL_UNPARK() ((void)0)
#endif

static int fl_erase4k(uint32_t off, uint32_t *took_us)
{
    uint32_t f;
    int rc;
    if (!fm1_capture_mutation_allowed())
        return FM1_CAPTURE_BUSY;
    (void)FL_PARK();
    f = irq_save();
    rc = FL_FAR(fl_erase4k_ram)(off, took_us);
    irq_restore(f);
    FL_UNPARK();
    return rc;
}

/* read through the SPI path (the XIP is off meanwhile): IRQs off for this call only */
static inline int fl_read(uint32_t off, uint8_t *dst, uint32_t n)
{
    uint32_t f;
    int rc;
    (void)FL_PARK();
    f = irq_save();
    rc = FL_FAR(fl_read_ram)(off, dst, n);
    irq_restore(f);
    FL_UNPARK();
    return rc;
}

static int fl_write(uint32_t off, const uint8_t *src_ram, uint32_t n)
{
    uint32_t took;
    if (n && !fm1_capture_mutation_allowed())
        return FM1_CAPTURE_BUSY;
    while (n) {
        uint32_t chunk = 256u - (off & 0xFFu);
        int rc;
        uint32_t f;
        if (chunk > n) chunk = n;
        (void)FL_PARK();
        f = irq_save();
        rc = FL_FAR(fl_prog_ram)(off, src_ram, chunk, &took);
        irq_restore(f);
        FL_UNPARK();
        if (rc) return rc;
        off += chunk; src_ram += chunk; n -= chunk;
    }
    return 0;
}

/* Read back through XIP (needs fl_plain_window_init) and compare. */
static int fl_verify_xip(uint32_t off, const uint8_t *ref, uint32_t n)
{
    const volatile uint8_t *p = (const volatile uint8_t *)FL_XIP(off);
    uint32_t i;
    for (i = 0; i < n; i++) if (p[i] != ref[i]) return -(int)(i + 1);
    return 0;
}

/* SPDX-License-Identifier: GPL-3.0-only */
/* FM-1 (AC79) performance counters, from JieLi's AC79 SDK (include_lib/driver/cpu/wl82/asm/csfr.h,
 * the corex2 block at 0x1EEE000; cpu/wl82/debug.c's cpu_effic_calc reads them):
 *
 *   C0_TL_CKCNT  core 0's clock cycles (64-bit; the low word is enough for deltas under ~17 s)
 *   C0_IF_UACNT  ... instruction-fetch cycles the SDK reports against TL_CKCNT: read as stalls
 *   C0_RD_UACNT  ... data reads, the same
 *   C0_WR_UACNT  ... data writes, the same
 *
 * Not verified on hardware. Whether TL_CKCNT counts without anything enabled is unknown: the caller
 * checks that it moves (fm1_perf_cycles_run) and falls back to TIMER4. The three stall counts are
 * enabled by DBG_CON bits 0-2 ("if/of/ex_inv_en" in the SDK, which may also arm fault exceptions):
 * only when asked, never at boot. Felucca's guards use DBG_EN (0x340), not DBG_CON (0x344). */
#pragma once
#include <stdint.h>
#include "fm1_time.h"

#define FM1_C0_IF_UACNTL (*(volatile uint32_t *)0x1EEE200u)
#define FM1_C0_RD_UACNTL (*(volatile uint32_t *)0x1EEE208u)
#define FM1_C0_WR_UACNTL (*(volatile uint32_t *)0x1EEE210u)
#define FM1_C0_TL_CKCNTL (*(volatile uint32_t *)0x1EEE218u)
#define FM1_DBG_CON (*(volatile uint32_t *)0x1EEE344u)

static inline uint32_t fm1_perf_cycles(void) { return FM1_C0_TL_CKCNTL; }

/* the cycle counter moves: two reads 100 us apart differ */
static inline int fm1_perf_cycles_run(void)
{
    uint32_t c0 = FM1_C0_TL_CKCNTL, t0 = fm1_ticks();
    while ((uint32_t)(fm1_ticks() - t0) < 100u * FM1_TICKS_PER_US)
        ;
    return FM1_C0_TL_CKCNTL != c0;
}

static inline void fm1_perf_stalls(uint32_t s[3])
{
    s[0] = FM1_C0_IF_UACNTL;
    s[1] = FM1_C0_RD_UACNTL;
    s[2] = FM1_C0_WR_UACNTL;
}

static inline void fm1_perf_stalls_enable(int on)
{
    if (on)
        FM1_DBG_CON |= 0x7u;
    else
        FM1_DBG_CON &= ~0x7u;
}

/* SPDX-License-Identifier: GPL-3.0-only */
/* X0X sequencer: runs in the audio ISR, sample accurate.
 *
 * The engine renders a block like this:
 *     while (n) {
 *         k = seq_until_event(&seq, n);       // samples until the next due event (>= 1)
 *         render k samples;
 *         seq_advance(&seq, k, &sink);        // moves time, fires the events now due
 *         n -= k;
 *     }
 * so a step lands on its exact sample, and engine code never sees time.
 *
 * Five parts, each with its own step counter (lengths and rates may differ):
 * 909, 808, 303 A, 303 B, BREAK (always 16ths, 16 to the bar). Each part plays its own
 * pattern (ppat[part]); track t is part t. The 909 part's length defines the bar: cued
 * patterns (or the next one of a chain, or the song's next bar) start when it wraps, and a
 * part whose pattern changed restarts on step 1 while the others keep running.
 *
 * Song: one entry per bar, each part's pattern and the part mutes. song_on plays it (and
 * loops); song_on + song_rec writes the live state (cues, mutes) into it from song_start on.
 *
 * Clock: internal (BPM) or external (24 ppqn MIDI clock, fed with seq_ext_clock()).
 * Swing delays every second 16th (909 shuffle: 0 = straight, 100 = 75 %).
 *
 * 303 semantics (as the TB-303 and Open303's sequencer):
 *   NOTE  plays; the gate falls at half the step, unless the step slides (BS_SLIDE)
 *         or the next step is a TIE, in which case it is held through.
 *   TIE   continues the sounding note (no retrigger); same gate rule.
 *   slide a NOTE following a step with BS_SLIDE glides from the held note
 *         (note_on with slide = 1, envelopes not retriggered).
 *   REST  releases.
 */
#pragma once
#include <stdint.h>
#include "pattern.h"

#define FS 44100u
#define TRK_DRUM 0                    /* + kit: 0 = 909, 1 = 808 */
#define TRK_BASS0 NKIT
#define TRK_BRK (NKIT + NBASS)
#define NTRACKS (NKIT + NBASS + 1)
/* mute bits: kit k voice v = k * NDRUM + v; then 303 A, 303 B, BREAK */
#define MUTE_BASS0 (NKIT * NDRUM)
#define MUTE_BRK (MUTE_BASS0 + NBASS)

/* the mute bits of part p (a drum machine: all its voices) */
static inline uint32_t seq_part_mask(int p)
{
    return p < NKIT ? ((1u << NDRUM) - 1u) << (p * NDRUM) : 1u << (MUTE_BASS0 + p - NKIT);
}

#define NSONG 192
#define SEQ_CH_OFF 0xFFu
/* a step's chance (the T_PROB lanes): 1-100 = that percentage, PROB_COND + k = the cycle k in the order
 * 1:2 2:2 1:3 2:3 3:3 1:4 ... 8:8 (A:B: on the A-th of every B passes of the part's pattern) */
#define PROB_COND 101
#define PROB_NCOND 35                    /* 2 + 3 + ... + 8 */
static inline void prob_cond(int k, int *a, int *b)
{
    int n = 2;
    while (k >= n) {
        k -= n;
        n++;
    }
    *a = k + 1;
    *b = n;
}
#define SONG_REP(b) (((b)->mute >> 5) + 1)    /* a bar plays 1-8 times: mute's bits 5-7 (the parts use 0-4) */
typedef struct {
    uint8_t pat[NTRACKS];             /* each part's pattern */
    uint8_t mute;                     /* bit p = part p muted */
} song_bar_t;
typedef struct {
    uint16_t len;                     /* bars; 0 = empty */
    uint8_t rsv[2];
    song_bar_t bar[NSONG];
} song_t;

typedef struct {
    int (*drum)(void *ctx, int kit, int voice, float vel);      /* 0: the hit did not play (its chance) */
    int (*bass_on)(void *ctx, int part, int note, int accent, int slide, int velocity); /* 0: chance skipped; do not echo MIDI */
    void (*bass_off)(void *ctx, int part);
    void (*brk)(void *ctx, int step16, int bar, float samples_per_16th, int enabled);
    void (*brk_stop)(void *ctx);
    void (*midi)(void *ctx, uint8_t status, uint8_t d1, uint8_t d2);   /* clock / transport / notes out */
    void (*step)(void *ctx, int part, int step);                        /* UI playhead (optional) */
    void *ctx;
} seq_sink_t;

#define SEQ_EXT_BEATS 8u              /* the tempo of an external clock: the mean over this many beats */
/* the clock source (GLO > MIDI > CLOCK SOURCE): AUTO follows a clock when one comes in (the default),
 * INTERNAL ignores MIDI Clock, Start, Stop and Continue, EXTERNAL plays only on the incoming clock */
#define SEQ_CLK_AUTO 0u
#define SEQ_CLK_INT 1u
#define SEQ_CLK_EXT 2u
/* AUTO and EXTERNAL follow one clock input (BEHAVIOR.md MID-15). The input of a MIDI in packet is in byte 0,
 * bits 4-5 (plat.h PLAT_MIDI_SRC): 0 USB, 1 Bluetooth, 2 TRS. The first input that sends Clock, Start or
 * Continue gets the clock. It keeps the clock until it sends nothing for SEQ_LOCK_T, or until SEQ_LOCK_T
 * after its Stop (then a Start or Continue of another input gets it). 0.4 s: more than 3 clocks at 20 BPM
 * (125 ms each), and less than the 0.5 s after which X0X goes to its internal clock or waits (MID-12, MID-13).
 * When another input gets the clock, the tempo measure starts again from the tempo that X0X has now. */
#define SEQ_LOCK_T (FS * 2u / 5u)

typedef struct {                      /* one part's runtime */
    uint8_t pos;                      /* current step */
    int8_t pp_dir;                    /* ping-pong direction */
    uint8_t started;                  /* the first step has fired since start */
    uint8_t sounding;                 /* 303: a note is held */
    uint8_t held_note;
    uint8_t ext_due;                  /* external clock: more steps due in one block, not yet played */
    uint32_t to_next;                 /* samples to the next step (Q8 fraction) */
    uint32_t to_off;                  /* 303: samples to the gate falling, Q8; 0 = none */
    uint32_t rng;                     /* DIR_RANDOM and auto-mutate */
    uint16_t bars;                    /* wraps since the pattern started (auto-mutate) */
    uint8_t ext_ticks;                /* external clock: ticks into this step */
    uint8_t rec_skip_step;            /* a live hit recorded on a step not played yet on this pass: */
    uint8_t rec_skip_pat;             /* that step, its pattern, and the voices (bit v; 303: bit 0) */
    uint8_t mut_steps;                /* random 303: low 7 pass count, high bit time-slot swing parity */
    uint16_t rec_skip;                /* that the step does not sound once (the key sounded) */
} seq_track_t;

typedef struct {
    uint32_t at, slot;
    uint8_t active, pat, first, last, prev, note, src, entered;
    uint8_t gen;       /* bumped on context cancel; a reopened DSP gate is not this generation */
    uint8_t own_ok;    /* 1 = own_* is an accepted live press of own_gen */
    uint8_t own_gen;   /* generation that accepted the live press */
    uint8_t own_src;   /* route of that press */
    uint8_t own_note;  /* pitch of that press */
} seq_bass_rec_t;

typedef struct {
    pattern_t *pat;                   /* NPAT patterns (the project's) */
    song_t *song;                     /* the project's song (may be 0) */
    volatile uint8_t playing;         /* 1 = running */
    volatile uint8_t ppat[NTRACKS];   /* the pattern each part plays */
    volatile uint8_t pcue[NTRACKS];   /* each part's cued pattern (0xFF = none) */
    volatile uint8_t chain_a, chain_b;/* chain range (whole patterns); a == b = no chain */
    volatile uint8_t song_on;         /* 1 = the song decides the patterns, bar by bar */
    volatile uint8_t song_rec;        /* with song_on: write the live state into the song */
    volatile uint16_t song_pos;       /* bar playing */
    volatile uint16_t song_start;     /* bar PLAY starts at */
    volatile uint8_t ext;             /* 1 = following an external clock */
    volatile uint8_t send_clock;      /* 1 = emit MIDI clock + transport when internal */
    volatile uint8_t send_notes;      /* 1 = echo the sequence on MIDI, on each part's channel */
    volatile uint8_t ch[NTRACKS];     /* each part's MIDI channel, 0-15 (in and out); SEQ_CH_OFF = none */
    uint8_t song_rep;                 /* the song bar playing: its passes still to play (SONG_REP) */
    volatile uint32_t mute;           /* MUTE_* bits */
    volatile uint32_t vmute;          /* drum tracks muted on their own (bit k * NDRUM + v): kept apart from
                                       * the part mutes, which the song and HOME set as a whole */
    volatile uint8_t accent_q7;       /* drum velocity of a non-accented hit, of 127 */
    volatile uint8_t drum_vel[NKIT][NDRUM]; /* per-voice step velocity from a T_VEL lane (engine); 0 = accent law */
    float bpm;                        /* internal tempo (UI writes; read per step) */
    float ext_bpm;                    /* tempo measured from the external clock */
    seq_track_t t[NTRACKS];           /* TRK_DRUM, TRK_BASS0.., TRK_BRK */
    /* Audio-side visual observer. UI reads only metro_view (one atomic byte):
     * 0 = stopped/waiting, 1..32 = quarter-note phase. Never schedules events. */
    uint32_t metro_phase, metro_period; /* elapsed/period in sample Q8 */
    float metro_bpm;
    uint8_t metro_tick;               /* accepted external clocks, independent of tempo ring */
    volatile uint8_t metro_view;
    uint32_t clk_to_next;             /* internal: samples to the next MIDI clock, Q8 */
    uint32_t ext_since;               /* samples since the last external clock (tempo estimate) */
    uint32_t ext_period;              /* smoothed samples per external clock, Q8 */
    uint32_t ext_now;                 /* samples, free running: the time base of the beat ring */
    uint32_t ext_beat[SEQ_EXT_BEATS]; /* ext_now at the last beats (24 external clocks each), a ring */
    uint8_t ext_nb, ext_bi, ext_q;    /* beats in the ring, the next ring slot, clocks into this beat */
    volatile uint32_t ext_pending;    /* external clocks received, not yet consumed */
    volatile uint32_t req_prior_ticks;/* ticks queued before latest Start/Continue request */
    volatile uint8_t req_start, req_stop, req_cont; /* transport requests from the UI / MIDI */
    volatile uint8_t midi_req;        /* 1 = the pending request came from MIDI in clip mode: no echo */
    volatile uint8_t rec_epoch, rec_dirty, rec_mask, rec_refused; /* accepted audio-side recorder context */
    volatile uint8_t rec_hold_mask;             /* finish an onset carried from SEQ into EDIT; no new onsets */
    seq_bass_rec_t rec_bass[NBASS];
    uint32_t mut_rng[NBASS];          /* auto-mutate random streams */
    uint8_t bass_notes_out[NBASS];    /* note echoed on MIDI, for the note off */
    uint8_t bass_out_valid[NBASS], bass_out_ch[NBASS]; /* note zero is valid; release on its original channel */
    uint8_t bass_slide_old[NBASS];    /* previous pitch whose MIDI gate overlaps a slide */
    uint8_t bass_slide_valid[NBASS], bass_slide_ch[NBASS];
    uint32_t bass_slide_off[NBASS];   /* remaining samples (Q8), zero = none */
    volatile uint8_t clk_src;         /* SEQ_CLK_*: the clock source that the UI sets */
    uint8_t clk_cur;                  /* SEQ_CLK_*: the clock source that seq_advance applied */
    uint8_t clk_lost;                 /* EXTERNAL: no clock now, the pause (or the wait) is done */
    volatile uint8_t req_rt;          /* 1 = the pending Start or Continue came from MIDI in (seq_midi_rt) */
    volatile uint8_t req_stop_rt;     /* 1 = pending Stop came from MIDI, not local PLAY */
    uint8_t start_local;              /* 1 = the last start came from PLAY (not from MIDI in) */
    uint32_t start_at;                /* ext_now at the last start */
    uint8_t clk_lock;                 /* the input that has the clock (MID-15): 0 none, else input + 1 */
    uint8_t clk_stop;                 /* 1: the last transport message of that input was a Stop */
    uint8_t clk_last;                 /* the input that had the clock last (input + 1): a change restarts the tempo measure */
    uint8_t ext_skip;                 /* 1: the next block of ticks gives no tick period (the first ticks of a new input) */
    uint32_t clk_lock_at;             /* ext_now at its last Clock, Start or Continue */
    uint32_t clk_stop_at;             /* ext_now at its last Stop */
} seq_t;

void seq_init(seq_t *s, pattern_t *patterns);
uint32_t seq_until_event(seq_t *s, uint32_t n);
void seq_advance(seq_t *s, uint32_t k, const seq_sink_t *o);
void seq_midi_flush(seq_t *s, const seq_sink_t *o); /* end tracked output without stopping local voices */

/* main loop / MIDI side (all are flag writes picked up at the next block) */
void seq_start(seq_t *s);             /* from step 1 of the current (or cued) pattern */
void seq_stop(seq_t *s);
void seq_continue(seq_t *s);
void seq_ext_clock(seq_t *s);         /* one 24-ppqn tick (USB MIDI 0xF8) */
int seq_midi_rt(seq_t *s, uint8_t st);  /* MIDI in 0xF8, 0xFA, 0xFB, 0xFC: 1 (INTERNAL drops them); else 0 */
int seq_clk_take(seq_t *s, uint8_t st, uint32_t src);   /* MIDI in from input src: 0 = another input has the clock */
void seq_clk_drop(seq_t *s, uint32_t src);  /* the link of input src ended: it loses the clock at once */
int seq_clock_waiting(const seq_t *s);  /* EXTERNAL: playing, but no clock for 0.5 s (it waits) */
void seq_cue(seq_t *s, int pattern);  /* every part, at the end of the bar (now, if stopped) */
void seq_cue_part(seq_t *s, int part, int pattern);
void seq_chain(seq_t *s, int a, int b);
int seq_cue_of(const seq_t *s, int part);   /* the part's cued pattern, or -1 */
int seq_part_muted(const seq_t *s, int part);

/* GM drum note per kit voice — seq MIDI out and engine MIDI in share one table */
extern const uint8_t GM_DRUM[NKIT][NDRUM];
/* Default 0-based MIDI channels for the five parts (seq_init + project_apply_io) */
extern const uint8_t SEQ_CH_DEFAULT[NTRACKS];

/* steps of one part's rate, in samples Q8 (no swing) at the current tempo */
uint32_t seq_step_q8(const seq_t *s, int rate);
float seq_tempo(const seq_t *s);      /* the tempo in effect (internal or measured) */
int seq_part_len(const seq_t *s, int t);         /* steps in part t's pattern */
int seq_next_step(seq_t *s, int t, int p);       /* the step after p (direction; no commit) */
int seq_rec_step(seq_t *s, int t);               /* the step a live hit now records on: the nearest */
void seq_rec_skip(seq_t *s, int t, int step, int voice);   /* that hit: its step does not sound it once */

#define SEQ_REC_LEGATO 0x40u /* accepted live incoming transition; never stored in step flags */
/* Live MIDI/keyboard edges, at the current audio clock. Last press owns the line;
 * older/different-route releases do not end it. Repeated identical presses count.
 * SEQ_REC_LEGATO is not ownership: overlap also needs the accepted note generation. */
void seq_rec_bass(seq_t *s, int b, int note, int velocity, int down, int src, int flags);
void seq_rec_bass_end(seq_t *s, int b);
/* Context cancel, part or pattern change, REC off, bulk finalize: drop the accepted
 * generation and finish the open capture. Press membership stays with the engine. */
void seq_rec_cancel(seq_t *s, int b);

#if X0X_BASS_NOTE_SOUND
/* Audio recorder storage transaction supplied by the product engine. */
int seq_bass_sound_prepare(seq_t *s,int voice,int pat,int step);
void seq_bass_sound_clear(seq_t *s,int voice,int pat,int step);
#endif

#!/bin/sh
# SPDX-License-Identifier: GPL-3.0-only
# bass303 port vs schwung-303's Open303, at BASS303_OS = 1, 2 and 4 (1 is informational:
# reported against the same targets, not part of the exit status).
#   tests/host/run_bass303.sh [-v]        -v prints every note and glide
# Builds the reference (Open303 C++ + drive.h, unmodified, from ../schwung-303 or $SCHWUNG303)
# with the host C++ compiler, the port with the host C compiler and the firmware's warning
# flags (any warning in bass303.c / bass303_test.c fails the run), runs the comparison for
# each factor, and writes build/bass303_demo.wav (port, BASS303_OS default) and
# build/bass303_ref.wav (reference) for listening. Exits non-zero on any failure.
set -e
cd "$(dirname "$0")/../.."
REF="${SCHWUNG303:-../schwung-303}/src/dsp"
[ -f "$REF/open303/rosic_Open303.cpp" ] || { echo "schwung-303 not found at $REF (set SCHWUNG303)"; exit 2; }
OUT=build/bass303_host
mkdir -p "$OUT/ref"
CC="${CC:-cc}"
CXX="${CXX:-c++}"
CFLAGS="-std=c99 -O2 -ffp-contract=off -Wall -Wextra -Wdouble-promotion"

# --- the reference: Open303 driven the way plugin.cpp drives it, pots mapped as plugin.cpp maps
# them (n = pot / 127). Where the port's panel differs from plugin.cpp (Tune is centred on 440,
# Slide / AccDec are live without the Devilfish switch, drive mix is fixed at 1) the same
# physical values are handed to Open303 directly, so the engines are compared, not the panels.
cat > "$OUT/ref303.cpp" <<'EOF'
#include "open303/rosic_Open303.h"
#include "drive.h"
using namespace rosic;
struct Ref { Open303 e; drive::Drive d; int held = -1; int dtype = 1; float damt = 0.0f; };
extern "C" {
void *ref_create(void)
{
    Ref *r = new Ref();
    r->e.setSampleRate(44100.0);
    r->d.prepare(44100.0);
    /* plugin.cpp apply_devil_mods() with the switch off */
    r->e.setAmpDecay(1230.0); r->e.setAccentDecay(200.0); r->e.setFeedbackHighpass(150.0);
    r->e.setNormalAttack(3.0); r->e.setSlideTime(60.0); r->e.setTanhShaperDrive(36.9);
    return r;
}
void ref_destroy(void *p) { delete (Ref *)p; }
void ref_set(void *p, int i, int pot)
{
    Ref *r = (Ref *)p;
    double n = pot / 127.0;
    switch (i) {
    case 0: r->e.setCutoff(linToExp(n, 0, 1, 314.0, 2394.0)); break;
    case 1: r->e.setResonance(linToLin(n, 0, 1, 0.0, 100.0)); break;
    case 2: r->e.setEnvMod(linToLin(n, 0, 1, 0.0, 100.0)); break;
    case 3: r->e.setDecay(linToExp(n, 0, 1, 200.0, 2000.0)); break;
    case 4: r->e.setAccent(linToLin(n, 0, 1, 0.0, 100.0)); break;
    case 5: r->e.setWaveform(pot ? 1.0 : 0.0); break;
    case 6: r->e.setTuning(440.0 + (pot - 64) * 0.625); break;
    case 7: r->e.setVolume(linToLin(n, 0, 1, -60.0, 0.0)); break;
    case 8: r->damt = (float)n; break;
    case 9: r->dtype = pot; if (pot) r->d.set_model(pot - 1); break;
    case 10: r->e.setSlideTime(linToLin(n, 0, 1, 2.0, 360.0)); break;
    case 11: r->e.setAccentDecay(linToLin(n, 0, 1, 30.0, 3000.0)); break;
    }
}
/* the port's note API in MIDI terms: velocity >= 100 is accent, an overlapping note slides */
void ref_note_on(void *p, int note, int acc, int slide)
{
    Ref *r = (Ref *)p;
    int vel = acc ? 127 : 64;
    if (slide && r->held >= 0) {
        r->e.noteOn(note, vel, 0.0);
        r->e.noteOn(r->held, 0, 0.0);
    } else {
        if (r->held >= 0)
            r->e.noteOn(r->held, 0, 0.0);
        r->e.noteOn(note, vel, 0.0);
    }
    r->held = note;
}
void ref_note_off(void *p)
{
    Ref *r = (Ref *)p;
    if (r->held >= 0)
        r->e.noteOn(r->held, 0, 0.0);
    r->held = -1;
}
void ref_render(void *p, float *out, int n)
{
    Ref *r = (Ref *)p;
    for (int i = 0; i < n; i++)
        out[i] = (float)r->e.getSample();
    if (r->dtype)
        r->d.process(out, n, r->damt, 1.0f);
}
}
EOF

# reference objects (warnings are Open303's own, not checked)
for f in "$REF"/open303/*.cpp "$OUT/ref303.cpp"; do
    o="$OUT/ref/$(basename "$f" .cpp).o"
    [ -f "$o" ] && [ "$o" -nt "$f" ] && [ "$o" -nt "$0" ] && continue
    $CXX -std=c++17 -O2 -w -I"$REF" -c "$f" -o "$o"
done
[ -f "$OUT/ref/fft4g.o" ] || $CC -O2 -w -c "$REF/open303/fft4g.c" -o "$OUT/ref/fft4g.o"

FAIL=0
for OS in 1 2 4; do
    WARN="$OUT/warn_$OS.txt"
    $CC $CFLAGS -DBASS303_OS=$OS -c firmware/src/dsp/bass303.c -o "$OUT/bass303_$OS.o" 2> "$WARN" \
        && $CC $CFLAGS -DBASS303_OS=$OS -c tests/host/bass303_test.c -o "$OUT/test_$OS.o" 2>> "$WARN" \
        || { cat "$WARN"; echo "run_bass303: build FAILED"; exit 1; }
    if [ -s "$WARN" ]; then echo "warnings (BASS303_OS=$OS):"; cat "$WARN"; FAIL=1; fi
    # the same port with the control rate at every sample, symbols renamed k1_*
    K1=""
    for f in env_time_ms init set note_on note_on_velocity note_off all_off render set_lite nparams param get; do K1="$K1 -Dbass303_$f=k1_bass303_$f"; done
    $CC $CFLAGS -DBASS303_OS=$OS -DBASS303_CTRL=1 $K1 -c firmware/src/dsp/bass303.c -o "$OUT/bass303_k1_$OS.o"
    rm -f "$OUT/bass303_test_$OS"     # macOS kills a binary relinked in place
    $CXX "$OUT/test_$OS.o" "$OUT/bass303_$OS.o" "$OUT/bass303_k1_$OS.o" "$OUT"/ref/*.o -o "$OUT/bass303_test_$OS"
    ARGS=""
    [ "$OS" = 2 ] && ARGS="--wav build"            # the default factor renders the demo
    [ "$OS" = 1 ] && ARGS="--info"                 # measured for comparison, not shipped
    "$OUT/bass303_test_$OS" $ARGS "$@" || FAIL=1
    echo
done
[ "$FAIL" = 0 ] && echo "run_bass303: PASS" || echo "run_bass303: FAIL"
exit $FAIL

